    $jp = ($p['language'] ?? '') === 'Japanese';
    return match ($r) {
        'Common', 'Uncommon' => 'About the rarity: Commons and Uncommons make up most of a set, so you need every one of them for a master set. Their PokÃ© Ball, Master Ball and promo versions can sell for many times the plain print.',
        'Rare' => 'About the rarity: a single black star in the corner marks a Rare, the slot one step above the commons in most packs.',
        'Holo Rare' => 'About the rarity: on a Holo Rare the PokÃ©monâ€™s picture is printed in holographic foil, the shine most people picture when they think of a good pull.',
        'Double Rare' => 'About the rarity: two black stars mean Double Rare, used for standard-art PokÃ©mon ex across Scarlet & Violet and Mega Evolution.',
        'Ultra Rare' => 'About the rarity: Ultra Rares carry artwork that runs edge to edge, on a textured foil you can feel with your thumb.',
        'Super Rare' => 'About the rarity: Super Rare (SR) is what Japanese sets call their full-art cards. It lines up with an English Ultra Rare, with edge-to-edge art and textured foil.',
        'Illustration Rare' => 'About the rarity: an Illustration Rare turns an everyday PokÃ©mon into a full-card painting, often a little scene from its world. They fall far less often than standard holos, and art collectors hunt them.',
        'Art Rare' => 'About the rarity: Art Rare (AR) is the Japanese equivalent of an Illustration Rare: a regular PokÃ©mon drawn as a full-card scene, pulled far less often than a holo.',
        'Special Illustration Rare' => 'About the rarity: Special Illustration Rares sit at the top of a setâ€™s art cards. Each gives a PokÃ©mon ex or a Supporter its own full illustration, wears two gold stars and turns up in very few packs.',
        'Special Art Rare' => 'About the rarity: Special Art Rare (SAR) is the Japanese label for a Special Illustration Rare, the setâ€™s premier art card and one of its scarcest pulls.',
        'Hyper Rare' => 'About the rarity: Hyper Rares are the all-gold cards, etched gold foil marked with three gold stars, and they rank among the toughest pulls in a set.',
        'Mega Hyper Rare' => 'About the rarity: Mega Hyper Rare tops the Mega Evolution rarity ladder; no card in those sets is harder to pull.',
        'Secret Rare' => 'About the rarity: a Secret Rare is numbered beyond the setâ€™s printed total, so it sits after the last card on the official list.',
        'Shiny Rare', 'Shiny Holo Rare' => 'About the rarity: a Shiny Rare shows the PokÃ©mon in its alternate shiny colors over a glittering foil background.',
        'Shiny Ultra Rare' => 'About the rarity: Shiny Ultra Rares pair edge-to-edge art with a shiny-colored PokÃ©mon, and they are some of the most wanted cards from the shiny sets.',
        'Radiant Rare' => 'About the rarity: Radiant PokÃ©mon arrived in Sword & Shield as shiny-colored cards with an etched foil finish. Deck rules allow just one Radiant PokÃ©mon.',
        'ACE SPEC Rare' => 'About the rarity: ACE SPEC Trainers are strong enough that a deck may include only one ACE SPEC card in total.',
        'Amazing Rare' => 'About the rarity: Amazing Rares, a Sword & Shield era rarity, have the PokÃ©mon breaking out of a rainbow paint-splash background.',
        'Black White Rare' => 'About the rarity: Black White Rare is the top rarity made specially for Black Bolt and White Flare.',
        'Promo' => 'About the rarity: you will not find promos in normal booster packs. They come from collection boxes, Elite Trainer Boxes, events and special products' . ($jp ? '' : ', and each carries a Black Star Promo number') . '.',
        default => '',
    };
}
function d_finish_note(array $p): string {
    $v = (string)$p['variant']; $n = (string)$p['card_name'];
    if (str_contains($n, 'Master Ball Pattern') || str_contains($v, 'Master Ball')) return 'Finish: Master Ball pattern reverse holo, the harder of the two pattern versions to find.';
    if (str_contains($n, 'Poke Ball Pattern') || str_contains($v, 'Poke Ball')) return 'Finish: PokÃ© Ball pattern reverse holo, with PokÃ© Balls printed into the foil.';
    if (preg_match('/Love Ball|Friend Ball|Quick Ball/', $v, $m)) return "Finish: {$m[0]} pattern reverse holo.";
    if (str_contains($n, 'Cosmos Holofoil')) return 'Finish: cosmos holofoil, the stars-and-planets foil seen on many promos.';
    if (str_starts_with($v, 'Reverse Holofoil')) return 'Finish: reverse holo, where the foil sits on the card frame around the picture rather than on the picture itself.';
    if ($v === 'Holofoil' && in_array($p['rarity'], ['Common', 'Uncommon', 'Rare'], true)) return 'Finish: holofoil.';
    return '';
}
function d_secret_note(array $p): string {
    if (preg_match('#^(\d+)/(\d+)$#', (string)$p['card_number'], $m) && (int)$m[1] > (int)$m[2] && $p['rarity'] !== 'Secret Rare')
        return "Note the number: {$p['card_number']} runs past the {$m[2]} cards the set officially lists, which marks it as a secret rare.";
    return '';
}
function d_clean_name(array $p): string {
    $n = trim((string)$p['card_name']);
    $n = trim(preg_replace('/\s*\((Master Ball|Poke Ball) Pattern\)/', '', $n));
    return $n !== '' ? $n : (string)$p['title'];
}
function d_set_link(array $p): string {
    if (empty($p['set_url']) || empty($p['set_name'])) return '';
    return '<a href="' . h($p['set_url']) . '">' . h($p['set_name']) . '</a>';
}
function d_card_page(array $p): string {
    foreach (auto_paths($p) as $path) if (preg_match('#^/cards/(' . implode('|', CARD_NAMES) . ')-pokemon-cards$#', $path, $m))
        return '<a href="' . $path . '">' . ucfirst($m[1]) . ' cards</a>';
    return '';
}
// The priciest singles we carry from the same set (read from the catalog, so it stays accurate).
function d_chase(array $p, int $n = 3): array {
    static $cache = [];
    if (empty($p['set_url'])) return [];
    if (!isset($cache[$p['set_url']])) {
        $cache[$p['set_url']] = all("SELECT id, handle, card_name, title, card_number FROM products WHERE set_url = ? AND section = 'Single Cards' AND published = 1 AND price_usd IS NOT NULL ORDER BY price_usd DESC LIMIT 12", [$p['set_url']]);
    }
    $out = []; $seen = [];
    foreach ($cache[$p['set_url']] as $r) {
        if ((int)$r['id'] === (int)($p['id'] ?? 0)) continue;
        $nm = trim(preg_replace(['/\s*\((Master Ball|Poke Ball) Pattern\)/', '#^\d+\*?/\d+\s+#'], '', $r['card_name'] ?: $r['title']));
        if (isset($seen[$nm]) || $nm === d_clean_name($p)) continue;
        $seen[$nm] = 1;
        $out[] = '<a href="/products/' . h($r['handle']) . '">' . h($nm . ($r['card_number'] ? ' ' . $r['card_number'] : '')) . '</a>';
        if (count($out) >= $n) break;
    }
    return $out;
}
function d_ship(array $p, bool $sealed = false): string {
    return d_pick($p, [
        'Shipping: leaves our warehouse in Japan within two days of payment by EMS, DHL or FedEx with tracking, and typically lands in the US in 3 to 6 working days.',
        'Shipping: tracked EMS, DHL or FedEx from Japan, sent within two days of payment. Orders above $2,000 get Standard shipping free.',
        'Shipping: priced in US dollars and sent from Japan with full tracking (EMS, DHL or FedEx) within two days of your payment clearing.',
    ], 11);
}
function d_lang_note(array $p): string {
    $lang = $p['language'] ?? 'English';
    if ($lang === 'Japanese') return d_pick($p, [
        'Language: Japanese. The card measures the standard 63 x 88 mm, exactly like an English card, so your usual sleeves, toploaders and binder pages fit.',
        'Language: Japanese. Same 63 x 88 mm footprint as English cards, and a print finish plenty of graders prefer.',
        'Language: Japanese. Japanese sets often arrive months ahead of their English counterparts, and the cards are the same size.',
    ], 9);
    if ($lang === 'Chinese') return 'Language: Simplified Chinese, an official print from the PokÃ©mon TCGâ€™s Chinese market, which has become a collecting niche of its own.';
    return d_pick($p, ['Language: English, the version on US store shelves.', 'Language: English. Standard 63 x 88 mm card.'], 9);
}

/* ------------------------------------------------------------------ singles */
function d_pokemon_single(array $p): array {
    $name = d_clean_name($p); $num = (string)$p['card_number']; $rar = (string)$p['rarity']; $type = (string)$p['card_type'];
    $setName = (string)$p['set_name']; $series = (string)$p['series'];
    $kind = preg_match('/\bEnergy\b/', $name) ? 'Energy card' : (is_trainer_card($p) ? 'Trainer card' : ($type !== '' ? "$type-type PokÃ©mon" : 'PokÃ©mon card'));
    if ($p['subsection'] === 'Jumbo cards') $kind = 'jumbo card';
    $lang = d_lang($p);
    $setTxt = $setName !== '' ? d_set_link($p) . ($series !== '' && !str_contains($setName, $series) ? ", part of the $series series" : '') : '';
    $id = '<strong>' . h($name) . '</strong>' . ($num !== '' ? " ($num)" : '');
    $rarTxt = $rar !== '' ? "$rar " : '';
    $s1 = $setTxt !== ''
        ? d_pick($p, [
            "Looking for $id? This $rarTxt$kind comes from " . ($lang === 'English' ? '' : "the $lang edition of ") . "$setTxt.",
            "$id appears in " . ($lang === 'English' ? '' : "the $lang release of ") . "$setTxt as " . d_an($rarTxt ?: $kind) . " $rarTxt$kind.",
            "Pulled from " . ($lang === 'English' ? '' : "$lang ") . "$setTxt, $id is " . d_an($rarTxt ?: $kind) . " $rarTxt$kind.",
        ], 21)
        : "$id is " . d_an($rarTxt ?: $kind) . " $rarTxt$kind from " . ($lang !== 'English' ? "a $lang release." : 'a special release.');
    if ($p['subsection'] === 'Jumbo cards') $s1 = "$id is an oversized jumbo card, the display piece packed into premium collection boxes. It is not made for play.";
    $para1 = trim($s1 . ' ' . d_finish_note($p) . ' ' . d_secret_note($p));
    $para2 = d_rarity_note($p);
    $chase = d_chase($p);
    $setLine = '';
    if ($chase) $setLine = d_pick($p, [
            'From the same set: ' . d_list($chase) . '. The <a href="' . h($p['set_url']) . '">complete ' . h($setName) . ' checklist</a> shows every card we carry and its price.',
            'Other big cards from ' . h($setName) . ' in our catalog: ' . d_list($chase) . '. Check the <a href="' . h($p['set_url']) . '">' . h($setName) . ' checklist</a> for the rest.',
        ], 23);
    $cp = d_card_page($p);
    if ($cp) $setLine .= ($setLine ? ' ' : '') . "More of this PokÃ©mon: our $cp page lists every version we stock.";
    $para3 = 'Condition: a single raw card, not graded. ' . d_lang_note($p) . ' ' . d_ship($p);
    return array_filter([$para1, $para2, $setLine, $para3]);
}
