        'css/admin.css' => ['text/css', <<<'__PKR_ASSET_1__'
/* Toramori admin â€” White theme */
:root{--bg:#F5F4F1;--card:#FFFFFF;--line:#E4E1DA;--line-strong:#8C8478;--ink:#17161A;--muted:#5E5850;--shu:#8F6B0E;--shu-soft:#F6EED8;--danger:#B5291F;--danger-soft:#F6E1DB;--ai:#1E3A5F;--ai-soft:#DFE6EF;
  --matcha:#3F6B3A;--matcha-soft:#E3EDDC;--kin:#7A5C28;--kin-soft:#F3EAD8;--font:"Zen Kaku Gothic New",system-ui,-apple-system,"Segoe UI",sans-serif;--mono:"IBM Plex Mono",ui-monospace,Menlo,monospace}
*{box-sizing:border-box}[hidden]{display:none!important}
body{margin:0;background:var(--bg);color:var(--ink);font:15px/24px var(--font);-webkit-font-smoothing:antialiased}
a{color:var(--ai)}a:hover{color:var(--shu)}
h1{font-size:26px;line-height:34px;margin:0 0 20px;font-weight:700}h2{font-size:17px;line-height:24px;margin:0 0 14px;font-weight:700}
.muted{color:var(--muted)}.small{font-size:13px;line-height:20px}.mono{font-family:var(--mono)}.amber-text{color:var(--kin)}
:focus-visible{outline:2px solid var(--ai);outline-offset:2px}
.side{position:fixed;inset:0 auto 0 0;width:220px;background:var(--card);border-right:1px solid var(--line);display:flex;flex-direction:column;padding:20px 12px}
.brand{display:flex;align-items:center;gap:10px;font-weight:700;font-size:17px;color:var(--ink);text-decoration:none;padding:0 8px 20px}
.side nav{display:flex;flex-direction:column;gap:2px;flex:1}
.side nav a{padding:9px 12px;border-radius:6px;color:var(--ink);text-decoration:none;display:flex;justify-content:space-between;align-items:center}
.side nav a:hover{background:var(--bg)}.side nav a[aria-current]{background:var(--ink);color:#fff}
.pill{background:var(--shu);color:#fff;border-radius:10px;padding:0 7px;font-size:12px;line-height:20px}
.side-foot{display:flex;flex-direction:column;gap:6px;padding:12px;border-top:1px solid var(--line);font-size:14px}
.main{margin-left:220px;padding:28px 32px 80px;max-width:1400px}.main.solo{margin:0 auto;max-width:520px;padding-top:12vh}
@media(max-width:860px){.side{position:static;width:auto;flex-direction:row;flex-wrap:wrap;align-items:center;padding:10px}.side nav{flex-direction:row;flex-wrap:wrap}.side-foot{flex-direction:row;border:0}.main{margin:0;padding:20px 14px 60px}}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:20px;margin-bottom:20px}
.card.flush{padding:0;overflow-x:auto}.card.narrow{max-width:460px;margin:0 auto}
.head{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.head h1{margin:0}
.btns{display:flex;flex-wrap:wrap;gap:8px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;height:40px;padding:0 16px;border:1px solid var(--line-strong);border-radius:6px;background:#fff;color:var(--ink);font:inherit;font-size:14px;font-weight:500;cursor:pointer;text-decoration:none;white-space:nowrap}
.btn:hover{background:var(--bg);color:var(--ink)}.btn.primary{background:var(--shu);border-color:var(--shu);color:#fff}.btn.primary:hover{filter:brightness(1.08)}
.btn.ghost{border-color:transparent;color:var(--ai)}.btn.danger{border-color:var(--danger);color:var(--danger)}.btn.big{height:48px;width:100%;font-size:16px}.btn.small{height:32px;padding:0 10px}
.btn[disabled]{opacity:.5;cursor:not-allowed}
label{display:flex;flex-direction:column;gap:6px;font-size:14px;font-weight:500;margin-bottom:14px}
label.inline{flex-direction:row;align-items:center;gap:8px;font-weight:400;margin-bottom:8px}
input,select,textarea{font:inherit;font-weight:400;border:1px solid var(--line-strong);border-radius:6px;padding:8px 10px;background:#fff;color:var(--ink);min-height:40px;width:100%}
textarea{line-height:22px}input[type=checkbox],input[type=radio]{width:18px;height:18px;min-height:0;accent-color:var(--shu)}input[type=file]{padding:6px;border-style:dashed}
.w-small{width:90px!important;display:inline-block}
.prefix{display:flex;align-items:stretch}.prefix span{display:flex;align-items:center;padding:0 10px;background:var(--bg);border:1px solid var(--line-strong);border-right:0;border-radius:6px 0 0 6px;font-family:var(--mono);font-size:13px;color:var(--muted)}.prefix input{border-radius:0 6px 6px 0}
.row3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 14px}.row6{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:0 14px}
@media(max-width:700px){.row3{grid-template-columns:1fr}}
.checks{display:flex;flex-wrap:wrap;gap:6px 20px}
.alert{background:var(--danger-soft);color:var(--danger);padding:10px 14px;border-radius:6px}
.flash{background:var(--matcha-soft);color:var(--matcha);padding:10px 14px;border-radius:6px;margin-bottom:16px;font-weight:500}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin-bottom:20px}
.kpi{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px;display:flex;flex-direction:column;gap:4px;color:var(--ink);text-decoration:none}
.kpi span{font-size:13px;color:var(--muted)}.kpi strong{font-size:26px;line-height:32px;font-family:var(--mono);font-weight:500}.kpi strong small{font-size:14px;color:var(--muted)}
a.kpi:hover{border-color:var(--line-strong);color:var(--ink)}
.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(380px,1fr));gap:20px}.cols .card{margin-bottom:0}
.checklist{list-style:none;padding:0;margin:0 0 12px}.checklist li{display:flex;gap:10px;align-items:center;padding:7px 0;border-bottom:1px solid var(--line)}
.tick{width:22px;height:22px;border-radius:50%;border:2px solid var(--line-strong);display:inline-grid;place-items:center;font-size:13px;flex:none}
.checklist li.done .tick{background:var(--matcha);border-color:var(--matcha);color:#fff}.checklist li.done a{color:var(--muted)}
.tbl{width:100%;border-collapse:collapse;font-size:14px;line-height:20px}
.tbl th{text-align:left;font-size:12px;letter-spacing:.04em;text-transform:uppercase;color:var(--muted);font-weight:500;padding:10px 12px;border-bottom:1px solid var(--line);background:#FBFAF8;white-space:nowrap}
.tbl td{padding:10px 12px;border-bottom:1px solid var(--line);vertical-align:middle}.tbl tr:last-child td{border-bottom:0}.tbl tr:hover td{background:#FBFAF8}
.tbl tr.faded td{opacity:.55}.w-check{width:36px}
.thumb{width:40px;height:40px;object-fit:contain;border:1px solid var(--line);border-radius:4px;display:block;background:var(--bg)}.thumb.empty{display:block}
.status{display:inline-block;font-size:12px;line-height:18px;padding:1px 8px;border-radius:10px;font-weight:500;white-space:nowrap}
.status.green{background:var(--matcha-soft);color:var(--matcha)}.status.amber{background:var(--kin-soft);color:var(--kin)}.status.blue{background:var(--ai-soft);color:var(--ai)}.status.grey{background:var(--bg);color:var(--muted)}
.filters{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:12px}.filters input,.filters select{width:auto;flex:1 1 150px}.filters input[type=search]{flex:2 1 240px}
.bulkbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:10px 12px}.bulkbar select{width:auto}.bulkbar label{margin:0}
.pager{display:flex;gap:16px;align-items:center;justify-content:center;margin:16px 0}
.tabs{display:flex;flex-wrap:wrap;gap:4px;border-bottom:1px solid var(--line);margin-bottom:16px}.tabs a{padding:8px 14px;color:var(--muted);text-decoration:none;border-bottom:2px solid transparent;margin-bottom:-1px}.tabs a[aria-current],.tabs a:hover{color:var(--ink);border-bottom-color:var(--shu)}
.edit-grid{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:20px;align-items:start}
@media(max-width:1100px){.edit-grid{grid-template-columns:1fr}}
.sticky-save{position:sticky;bottom:0;display:flex;flex-direction:column;gap:8px;background:var(--bg);padding:12px 0 16px;z-index:5}
.photo{border:1px dashed var(--line-strong);border-radius:8px;min-height:160px;display:grid;place-items:center;margin-bottom:14px;background:var(--bg)}.photo img{max-height:260px;object-fit:contain}
.editor{border:1px solid var(--line-strong);border-radius:8px;overflow:hidden;margin-bottom:14px}
.editor .toolbar{display:flex;flex-wrap:wrap;gap:4px;padding:6px;border-bottom:1px solid var(--line);background:#FBFAF8}
.editor .toolbar button,.tb-file{height:30px;min-width:34px;padding:0 8px;border:1px solid var(--line);border-radius:4px;background:#fff;cursor:pointer;font:inherit;font-size:13px;display:inline-flex;align-items:center;margin:0;flex-direction:row;font-weight:400}
.editor .area{padding:14px 16px;outline:none;line-height:26px;max-height:70vh;overflow:auto}
.editor .area h2{font-size:21px}.editor .area img{max-width:100%}
.editor textarea.source{display:block;border:0;border-radius:0;min-height:300px;font-family:var(--mono);font-size:13px}
.serp{border:1px solid var(--line);border-radius:8px;padding:12px;font-family:Arial,sans-serif;margin-top:6px}
.serp-url{font-size:12px;color:#4d5156}.serp-title{font-size:18px;line-height:24px;color:#1a0dab;margin:2px 0}.serp-desc{font-size:13px;line-height:20px;color:#4d5156}
.progress .bar{height:10px;background:var(--bg);border-radius:6px;overflow:hidden;margin-bottom:8px}.progress .bar span{display:block;height:100%;background:var(--matcha);width:0;transition:width .3s}

.side nav a[aria-current]{background:#0B0A08;color:#E7CF8E}
/* reviews */
.note{background:#FFF8E6;border:1px solid #EAD9A6;border-radius:6px;padding:10px 12px;color:#5E4B1C}
.narrow-form{max-width:900px}
.tbl td .btns{display:flex;gap:6px;flex-wrap:wrap}.tbl td form{margin:0}
