/* Toramori storefront */
(() => {
  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const PK = window.PK || {};
  const fmt = usd => {
    const v = usd * (PK.rate || 1);
    return (PK.sym || '$') + (PK.cur === 'JPY' ? Math.round(v).toLocaleString('en-US') : v.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2}));
  };
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));

  async function api(url, body) {
    const opt = body ? {method: 'POST', headers: {'Content-Type': 'application/json', 'X-CSRF': PK.csrf}, body: JSON.stringify(body)} : {};
    const r = await fetch(url, opt);
    if (!r.ok) throw new Error('Request failed');
    return r.json();
  }
  let toastT;
  function toast(html) {
    const t = $('.toast'); t.innerHTML = html; t.hidden = false;
    clearTimeout(toastT); toastT = setTimeout(() => (t.hidden = true), 3500);
  }
  function setCount(n) { $$('[data-cart-count]').forEach(b => (b.textContent = n)); }

  /* ---------- dropdown menus */
  const items = $$('[data-menu]');
  const closeAll = except => items.forEach(it => { if (it !== except) { const b = $('.nav-btn', it); b.setAttribute('aria-expanded', 'false'); $('.panel', it).hidden = true; } });
  const desktop = () => window.matchMedia('(min-width: 1021px)').matches;
  items.forEach(it => {
    const btn = $('.nav-btn', it), panel = $('.panel', it);
    const open = () => { closeAll(it); btn.setAttribute('aria-expanded', 'true'); panel.hidden = false; };
    btn.addEventListener('click', () => (btn.getAttribute('aria-expanded') === 'true' ? (btn.setAttribute('aria-expanded', 'false'), (panel.hidden = true)) : open()));
    it.addEventListener('mouseenter', () => desktop() && open());
    it.addEventListener('mouseleave', () => desktop() && closeAll());
  });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') { closeAll(); closeDrawer(); } });
  document.addEventListener('click', e => { if (desktop() && !e.target.closest('[data-menu]')) closeAll(); });
  const mb = $('[data-mobile-menu]');
  if (mb) mb.addEventListener('click', () => { const nav = $('.nav'); const on = nav.classList.toggle('open'); if (on) { window.scrollTo(0, 0); nav.style.top = Math.round($('.hdr').getBoundingClientRect().bottom) + 'px'; } mb.setAttribute('aria-expanded', on); document.body.style.overflow = on ? 'hidden' : ''; });

  /* ---------- quantity steppers */
  function clampQty(form, v) {
    const step = +form.dataset.step || 1, moq = +form.dataset.moq || 1, min = form.hasAttribute('data-set') ? 0 : moq;
    v = Math.max(min, Math.round(v) || 0);
    if (v > 0 && v < moq) v = moq;
    if (v > moq && (v - moq) % step) v += step - ((v - moq) % step);
    return v;
  }
  document.addEventListener('click', e => {
    const b = e.target.closest('[data-dec],[data-inc]');
    if (!b) return;
    const form = b.closest('form'), inp = $('input[name=qty]', form);
    const step = +form.dataset.step || 1, moq = +form.dataset.moq || 1;
    let v = +inp.value || 0;
    if (b.hasAttribute('data-inc')) v = v < moq ? moq : v + step;
    else v = v - step < moq ? (form.hasAttribute('data-set') ? 0 : moq) : v - step;
    inp.value = clampQty(form, v);
    inp.dispatchEvent(new Event('change', {bubbles: true}));
  });
  document.addEventListener('change', e => {
    if (e.target.name === 'qty' && e.target.closest('[data-add],[data-set]')) {
      const form = e.target.closest('form');
      e.target.value = clampQty(form, +e.target.value);
      if (form.hasAttribute('data-pdp')) updatePdp(+e.target.value);
      if (form.hasAttribute('data-set')) setLine(form);
    }
  });

  /* ---------- add to order */
  document.addEventListener('submit', async e => {
    const form = e.target.closest('[data-add]');
    if (!form) return;
    e.preventDefault();
    const inp = $('input[name=qty]', form);
    const qty = clampQty(form, +inp.value);
    const btn = $('button[type=submit]', form); btn.disabled = true;
    try {
      const c = await api('/api/cart', {action: 'add', id: +form.dataset.id, qty});
      setCount(c.count);
      const line = c.lines.find(l => l.id === +form.dataset.id);
      toast(`Added ${qty} Ã— ${esc(line ? line.title : 'item')}. <a href="/cart">View order (${c.count})</a>`);
      renderDrawer(c);
    } catch { toast('Could not add that item. Refresh the page and try again.'); }
    btn.disabled = false;
  });

  /* ---------- product page live pricing */
  function updatePdp(q) {
    const t = $('[data-ladder]'); const unitEl = $('[data-unit]'); const totalEl = $('[data-total]');
    let tiers = t ? JSON.parse(t.dataset.ladder) : null;
    const form = $('[data-pdp]');
    if (!tiers) { const u = unitEl ? parseFloat(unitEl.dataset.usd || 0) : 0; return; }
    let idx = 0; tiers.forEach((tr, i) => { if (q >= tr[0]) idx = i; });
    $$('tbody tr', t).forEach((r, i) => r.classList.toggle('is-active', i === idx));
    unitEl.textContent = tiers[idx][2];
    $('[data-qty-label]').textContent = q;
    totalEl.textContent = fmt(tiers[idx][1] * q / (PK.rate ? 1 : 1));
    const nudge = $('[data-nudge]'), next = tiers[idx + 1];
    if (nudge) { nudge.hidden = !next; if (next) nudge.textContent = `${next[0] - q} more and each unit drops to ${next[2]}.`; }
  }
  const pdpQty = $('[data-pdp] input[name=qty]');
  if (pdpQty && !$('[data-ladder]')) {
    // single-price products: keep the total in step with quantity
    const unitTxt = $('[data-unit]'), total = $('[data-total]');
    const base = parseFloat((total?.textContent || '').replace(/[^0-9.]/g, '')) / (+pdpQty.value || 1);
    pdpQty.addEventListener('change', () => { if (total) total.textContent = (PK.sym || '$') + (base * +pdpQty.value).toLocaleString('en-US', {minimumFractionDigits: PK.cur === 'JPY' ? 0 : 2, maximumFractionDigits: PK.cur === 'JPY' ? 0 : 2}); $('[data-qty-label]').textContent = pdpQty.value; });
  }

  /* ---------- cart page */
  async function setLine(form) {
    const qty = +$('input[name=qty]', form).value;
    await api('/api/cart', {action: 'set', id: +form.dataset.id, qty});
    location.reload();
  }
  document.addEventListener('click', async e => {
    const r = e.target.closest('[data-remove]');
    if (r) { await api('/api/cart', {action: 'remove', id: +r.dataset.remove}); location.reload(); }
    if (e.target.closest('[data-clear]') && confirm('Remove everything from your order?')) { await api('/api/cart', {action: 'clear'}); location.reload(); }
  });

  /* ---------- mini cart drawer */
  const drawer = $('#drawer');
  function renderDrawer(c) {
    if (!drawer) return;
    $('[data-drawer-body]').innerHTML = c.lines.length ? c.lines.map(l => `<div class="dline">${l.image ? `<img src="${esc(l.image)}" alt="">` : '<span></span>'}<div><a href="/products/${esc(l.handle)}">${esc(l.title)}</a><div class="small muted">${l.qty} Ã— ${esc(l.unit)}</div>${l.next ? `<div class="small ai">${esc(l.next)}</div>` : ''}</div><strong class="mono small">${esc(l.line)}</strong></div>`).join('') : '<p class="muted">Your order is empty.</p>';
    $('[data-drawer-subtotal]').textContent = c.subtotal;
    $('[data-drawer-min]').textContent = c.min_ok ? '' : `Minimum order is ${c.min} including shipping.`;
  }
  function closeDrawer() { if (drawer) drawer.hidden = true; }
  $$('[data-cart-open]').forEach(a => a.addEventListener('click', async e => {
    if (location.pathname === '/cart' || !drawer) return;
    e.preventDefault();
    renderDrawer(await api('/api/cart'));
    drawer.hidden = false; $('[data-drawer-close]').focus();
  }));
  $('[data-drawer-close]')?.addEventListener('click', closeDrawer);

  /* ---------- filters */
  const ff = $('[data-filters]');
  if (ff) {
    ff.addEventListener('change', e => { if (e.target.type === 'checkbox' && window.matchMedia('(min-width: 901px)').matches) { const fd = new FormData(ff); fd.delete('page'); ff.requestSubmit(); } });
    $$('[data-fsearch]').forEach(inp => inp.addEventListener('input', () => {
      const q = inp.value.toLowerCase();
      $$('.check', inp.parentElement).forEach(l => (l.style.display = l.textContent.toLowerCase().includes(q) ? '' : 'none'));
    }));
  }
  const ft = $('[data-filters-toggle]');
  if (ft) {
    const f = $('#filters');
    const close = document.createElement('button'); close.type = 'button'; close.className = 'btn btn-sm filters-close'; close.textContent = 'Close filters';
    f.prepend(close);
    ft.addEventListener('click', () => { f.classList.add('open'); ft.setAttribute('aria-expanded', 'true'); });
    close.addEventListener('click', () => { f.classList.remove('open'); ft.setAttribute('aria-expanded', 'false'); });
  }
  $$('select[data-nav]').forEach(s => s.addEventListener('change', () => (location.href = s.value)));

  /* ---------- instant search */
  const debounce = (fn, ms) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; };
  $$('[data-instant]').forEach(inp => {
    const box = inp.parentElement.querySelector('.instant');
    inp.addEventListener('input', debounce(async () => {
      const q = inp.value.trim();
      if (q.length < 2) { box.hidden = true; return; }
      const rows = await api('/api/search?q=' + encodeURIComponent(q));
      box.innerHTML = rows.map(p => `<a href="/products/${esc(p.handle)}">${p.image ? `<img src="${esc(p.image)}" alt="">` : ''}<span class="flex1"><span>${esc(p.title)}</span><br><span class="small muted">${esc([p.set, p.number].filter(Boolean).join(' Â· '))}</span></span><span class="mono small">${esc(p.price)}</span></a>`).join('') + `<a class="all" href="/search?q=${encodeURIComponent(q)}">See all results â†’</a>`;
      box.hidden = false;
    }, 200));
    document.addEventListener('click', e => { if (!inp.parentElement.contains(e.target)) box.hidden = true; });
  });

  /* ---------- quick order */
  const qrow = p => `<div class="qrow">${p.image ? `<img src="${esc(p.image)}" alt="">` : '<span></span>'}<div><a href="/products/${esc(p.handle)}">${esc(p.title)}</a><div class="small muted">${esc([p.set, p.number, p.lang !== 'English' ? p.lang : ''].filter(Boolean).join(' Â· '))} Â· ${esc(p.price)}${p.best ? ' Â· ' + esc(p.best) : ''} Â· MOQ ${p.moq}${p.step > 1 ? ' in ' + p.step + 's' : ''}</div></div>${p.in_stock ? `<form class="add add-row" data-add data-id="${p.id}" data-step="${p.step}" data-moq="${p.moq}"><div class="qty"><button type="button" data-dec aria-label="Fewer">âˆ’</button><input type="number" name="qty" value="${p.qty || p.moq}" aria-label="Quantity"><button type="button" data-inc aria-label="More">+</button></div><button class="btn btn-primary btn-sm" type="submit">Add</button></form>` : '<span class="tag">Sold out</span>'}</div>`;
  const qs = $('[data-quick-search]');
